style.css:
@-moz-document domain("studysync.com") {
/* Studysync Darkmode by Mang0o */

.fullscreen__left,
.fullscreen__right {
    background: #1c1c1e;
}

.multitool__header.stuck {
    background-color: #1c1c1e;
}

.fullscreen__bar {
    background: #1c1c1e;
}
body {
    color: white;
    background: #1c1c1e;
}
div {
    background-color: #1c1c1e;
    color: white;
}
nav.subnav {
    background-color: #1c1c1e;
    color: #1c1c1e;
}
header#header {
    background-color: #1c1c1e;
}
p {
    color: white;
    background-color: #1c1c1e;
}
h1 {
    color: white;
    background-color: #1c1c1e;
}
h2 {
    color: white;
    background-color: #1c1c1e;
}
h3 {
    color: white;
    background-color: #1c1c1e;
}
div.assignment_header.ng-scope.allowThumb {
    background-color: #1c1c1e;
    color: #1c1c1e;
}
div.ng-scope {
    background: #1c1c1e;
    color: white;
}

.headline--strikethrough h1,
.headline--strikethrough h2,
.headline--strikethrough h3,
.headline--strikethrough h4,
.headline--strikethrough h5,
.headline--strikethrough span {
    background: #1c1c1e;
}
}
